<?php
require_once __DIR__ . '/_helpers.php';
if (!function_exists('pm_suite_programmes')) { function pm_suite_programmes(mysqli $conn,int $managerId): array {$rows=[];$s=$conn->prepare('SELECT id,name,status FROM programmes WHERE programme_manager_id=? ORDER BY name');if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}return $rows;} }
if (!function_exists('pm_suite_cohorts')) { function pm_suite_cohorts(mysqli $conn,int $managerId): array {$rows=[];$s=$conn->prepare('SELECT c.id,c.name,c.programme_id,p.name AS programme_name FROM cohorts c JOIN programmes p ON p.id=c.programme_id WHERE p.programme_manager_id=? ORDER BY p.name,c.name');if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}return $rows;} }
if (!function_exists('pm_suite_valid_scope')) { function pm_suite_valid_scope(mysqli $conn,int $programmeId,int $cohortId,int $managerId): bool {$s=$conn->prepare('SELECT p.id FROM programmes p WHERE p.id=? AND p.programme_manager_id=?');if(!$s)return false;$s->bind_param('ii',$programmeId,$managerId);$s->execute();$ok=(bool)$s->get_result()->fetch_assoc();$s->close();if(!$ok)return false;if($cohortId>0){$s=$conn->prepare('SELECT c.id FROM cohorts c JOIN programmes p ON p.id=c.programme_id WHERE c.id=? AND c.programme_id=? AND p.programme_manager_id=?');if(!$s)return false;$s->bind_param('iii',$cohortId,$programmeId,$managerId);$s->execute();$ok=(bool)$s->get_result()->fetch_assoc();$s->close();}return $ok;} }
if (!function_exists('pm_suite_layout_start')) { function pm_suite_layout_start(string $title,string $currentPage): void { $GLOBALS['pageTitle']=$title;$GLOBALS['currentPage']=$currentPage; echo '<link rel="stylesheet" href="'.e(url('css/programme_management_suite.css')).'?v=20261026">'; } }
?>